def dedupe_contacts_and_backfill_ledger(apps, schema_editor):
    """Remove duplicate CampaignContact rows, then seed RecipientSend from Log.

    Duplicate contact rows were created because CSV imports did not dedupe
    addresses. We keep the most useful row (sent > failed > pending > skipped,
    then oldest id) before the unique constraint is added.
    """
    CampaignContact = apps.get_model("campaigns", "CampaignContact")
    Log = apps.get_model("campaigns", "Log")
    RecipientSend = apps.get_model("campaigns", "RecipientSend")

    duplicates = list(
        CampaignContact.objects.values("campaign_id", "recipient")
        .annotate(n=Count("id"))
        .filter(n__gt=1)
    )
    priority = {"sent": 0, "failed": 1, "pending": 2, "skipped": 3}

    for dup in duplicates:
        rows = list(
            CampaignContact.objects.filter(
                campaign_id=dup["campaign_id"], recipient=dup["recipient"]
            )
        )
        if len(rows) < 2:
            continue
        keep = min(rows, key=lambda c: (priority.get(c.status, 9), c.id))
        CampaignContact.objects.filter(
            campaign_id=dup["campaign_id"], recipient=dup["recipient"]
        ).exclude(id=keep.id).delete()

    batch = []
    success_logs = Log.objects.filter(status="success").select_related("campaign").iterator()
    for log in success_logs:
        if not log.campaign_id or not log.recipient:
            continue
        batch.append(
            RecipientSend(
                user_id=log.campaign.user_id,
                recipient=log.recipient.strip().lower(),
                campaign_id=log.campaign_id,
                sent_at=log.created_at,
            )
        )
        if len(batch) >= 1000:
            RecipientSend.objects.bulk_create(batch)
            batch = []
    if batch:
        RecipientSend.objects.bulk_create(batch)


